import { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../auth/AuthContext';

function Register() {
  const { register, isLoggedIn } = useAuth();
  const navigate = useNavigate();
  const [form, setForm] = useState({ email: '', password: '', displayName: '' });
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (isLoggedIn) {
      navigate('/', { replace: true });
    }
  }, [isLoggedIn, navigate]);

  async function handleSubmit(e) {
    e.preventDefault();
    setLoading(true);
    setError(null);
    try {
      await register(form.email, form.password, form.displayName);
      navigate('/');
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }

  const inputClass = 'w-full rounded-lg border border-slate-300 bg-white px-3 py-2 focus:border-amber-400 focus:outline-none focus:ring-2 focus:ring-amber-100';

  return (
    <div className="mx-auto max-w-md px-4 py-16">
      <h1 className="mb-6 text-center text-2xl font-semibold text-slate-900">📚 สมัครสมาชิก NangSuKub</h1>
      <form onSubmit={handleSubmit} className="space-y-4 rounded-xl border border-amber-100 bg-white p-6 shadow-sm">
        <div>
          <label className="block text-sm font-medium text-slate-700 mb-1">ชื่อที่แสดง</label>
          <input type="text" value={form.displayName} onChange={e => setForm({ ...form, displayName: e.target.value })}
            required className={inputClass} />
        </div>
        <div>
          <label className="block text-sm font-medium text-slate-700 mb-1">อีเมล</label>
          <input type="email" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })}
            required className={inputClass} />
        </div>
        <div>
          <label className="block text-sm font-medium text-slate-700 mb-1">รหัสผ่าน (อย่างน้อย 8 ตัวอักษร)</label>
          <input type="password" value={form.password} onChange={e => setForm({ ...form, password: e.target.value })}
            required minLength={8} className={inputClass} />
        </div>
        {error && <p className="text-sm text-red-600">{error}</p>}
        <button type="submit" disabled={loading}
          className="w-full rounded-lg bg-amber-500 py-2 text-sm font-medium text-white hover:bg-amber-600 disabled:bg-slate-300">
          {loading ? 'กำลังสมัคร...' : 'สมัครสมาชิก'}
        </button>
        <p className="text-center text-sm text-slate-500">
          มีบัญชีแล้ว?{' '}
          <Link to="/login" className="text-amber-600 hover:underline">เข้าสู่ระบบ</Link>
        </p>
      </form>
    </div>
  );
}

export default Register;
